import{_ as i,a as p}from"./chunks/single_macro_morph.C_9wKYm5.js";import{_ as h,C as r,o as g,c as d,a3 as s,j as n,a as o,E as a,w as m}from"./chunks/framework.CCylkYel.js";const u="/screens/snapshots/knob_bank_fade.png",b="/screens/snapshots/knob_bank_morph.png",k="/screens/macros/macro_morph_amount.png",y=JSON.parse('{"title":"Morph","description":"","frontmatter":{},"headers":[],"relativePath":"snapshots/morph.md","filePath":"snapshots/morph.md"}'),f={name:"snapshots/morph.md"};function A(P,t,T,w,M,E){const e=r("C"),l=r("ManualRelated");return g(),d("div",null,[t[17]||(t[17]=s('<h1 id="morph" tabindex="-1">Morph <a class="header-anchor" href="#morph" aria-label="Permalink to &quot;Morph&quot;">​</a></h1><p>A morph takes you from what you hear now to a snapshot pad, smoothly. It works on every bank: <a href="./knob-bank">knobs</a>, <a href="./rack-bank">racks</a> and <a href="./lfo-bank">LFOs</a>.</p><h2 id="glide-to-a-pad" tabindex="-1">Glide to a pad <a class="header-anchor" href="#glide-to-a-pad" aria-label="Permalink to &quot;Glide to a pad&quot;">​</a></h2>',3)),n("p",null,[t[0]||(t[0]=o("Set the bank's ",-1)),t[1]||(t[1]=n("strong",null,"FADE TIME",-1)),t[2]||(t[2]=o(" on its pencil tab, then press ",-1)),a(e,{action:"select"}),t[3]||(t[3]=o()),t[4]||(t[4]=n("strong",null,"Select",-1)),t[5]||(t[5]=o(" on a filled pad. The scene glides in over that time, at the project tempo. With ",-1)),t[6]||(t[6]=n("strong",null,"FADE TIME OFF",-1)),t[7]||(t[7]=o(" it lands at once.",-1))]),t[18]||(t[18]=s('<p>While a bank glides, the line under the header fills from left to right. When the line is full, the bank is about to land; it goes back to normal once it has. A blend by hand doesn&#39;t show it.</p><p><img src="'+u+'" alt="Gliding to 04 DROP, half the FADE TIME gone" class="screen"></p><p>Press the pad you&#39;re on after changing something and it glides back to it. If nothing it would change differs, it lands at once.</p><p>Pads, MIDI and snapshot knobs glide this way. <a href="./lanes">Arrange</a> uses its own <strong>FADE TIME</strong>. An Arrange row on the pad you&#39;re on does the same, over Arrange <strong>FADE TIME</strong>.</p><p>Press another filled pad during a glide and it heads there instead, from what you hear at that moment.</p><h2 id="blend-by-hand" tabindex="-1">Blend by hand <a class="header-anchor" href="#blend-by-hand" aria-label="Permalink to &quot;Blend by hand&quot;">​</a></h2>',6)),n("p",null,[t[8]||(t[8]=o("Hold ",-1)),a(e,{action:"select-long"}),t[9]||(t[9]=o()),t[10]||(t[10]=n("strong",null,"Select",-1)),t[11]||(t[11]=o(" on a filled pad and turn: ",-1)),t[12]||(t[12]=n("strong",null,"0%",-1)),t[13]||(t[13]=o(" is your sound, ",-1)),t[14]||(t[14]=n("strong",null,"100%",-1)),t[15]||(t[15]=o(" is the pad. Turn faster for bigger steps.",-1))]),t[19]||(t[19]=s('<p><img src="'+b+'" alt="Blending toward 04 DROP at 34%" class="screen"></p><ul><li>Let go below <strong>100%</strong> and the blend stays there. Hold <strong>Select</strong> and turn again to carry on.</li><li>Let go at <strong>100%</strong> and the pad becomes the current scene.</li><li>Turn back to <strong>0%</strong> and the morph ends. You hear your sound again, with anything you changed on the way.</li></ul><p>This works with <strong>FADE TIME OFF</strong> too, and during a glide.</p><p>Moving a knob or a setting during a morph keeps your value. The morph stops moving it.</p><h2 id="map-the-amount-to-a-knob" tabindex="-1">Map the amount to a knob <a class="header-anchor" href="#map-the-amount-to-a-knob" aria-label="Permalink to &quot;Map the amount to a knob&quot;">​</a></h2><p>On the bank&#39;s pencil tab, choose <strong>MAPPING</strong> → <strong>MAP MORPH</strong>. Pick a knob (<strong>INTERNAL MAPPING</strong>) or learn a CC or 14-bit CC (<strong>EXTERNAL MAPPING</strong>).</p><p>The mapped knob is a crossfader: <strong>0%</strong> is your sound, <strong>100%</strong> is the bank&#39;s current snapshot. Recall another pad and the knob aims at that one.</p><p><img src="'+k+'" alt="MORPH macro on the macro grid" class="screen"></p><p>On the macro grid, <strong>PART</strong> picks the bank (<strong>KNOBS</strong>, <strong>LFOS</strong>, <strong>RACK1</strong>–<strong>RACK8</strong>). <strong>INVERT</strong> makes turning down morph up.</p><p><img src="'+i+'" alt="Morph knob on Perform at 42%" class="screen"></p><p>The knob never jumps the sound. When it doesn&#39;t match the amount, turn it to the mark on the bar to pick it up.</p><p><img src="'+p+'" alt="Morph knob waiting to catch 0%" class="screen"></p><p><strong>MAPPING</strong> → <strong>UNMAP MORPH</strong> removes the knob. To drop a learned CC, open <strong>MAP MORPH</strong> → <strong>EXTERNAL MAPPING</strong>: a mapped row offers <strong>LEARN AGAIN</strong> / <strong>REMOVE MAPPING</strong>.</p><h2 id="what-a-morph-moves" tabindex="-1">What a morph moves <a class="header-anchor" href="#what-a-morph-moves" aria-label="Permalink to &quot;What a morph moves&quot;">​</a></h2><ul><li>Knob positions, LFO rate, depth, phase and offset, and device values with a range glide all the way, unless their <a href="./#keep-one-parameter-under-your-hands">ALLOW MORPH</a> is <strong>NO</strong>.</li><li>In a knob morph, a parameter a knob controls follows the knob, except one that is <strong>IN SNAPSHOT YES</strong> with <strong>ALLOW MORPH NO</strong>.</li><li>On/off values and choices switch in one step, at the point their <strong>ALLOW MORPH</strong> sets.</li><li>Notes and channels switch at <strong>100%</strong>.</li><li>A Delay <strong>DELAY TIME</strong>, an Arpeggiator <strong>RATE</strong> or an Envelope time with <strong>SYNC</strong> on moves through note values only. When <strong>SYNC</strong> differs between your sound and the pad, the time jumps to the pad&#39;s length at <strong>50%</strong>; <strong>SYNC</strong> follows at its own <strong>ALLOW MORPH</strong> point.</li><li>A Step Seq pattern switches as a whole at <strong>50%</strong>; the playhead keeps running.</li><li>Each LFO keeps moving its targets during the morph.</li><li>Anything set to <strong>IN SNAPSHOT NO</strong> stays put in a rack or LFO morph. In a knob morph, a parameter a knob controls still follows its knob.</li></ul><p>While a bank glides, its pads can&#39;t be taken, deleted, copied, swapped or moved. The screen says <strong>WAIT FOR THE GLIDE TO END</strong>; try again when it ends.</p>',16)),a(l,null,{default:m(()=>[...t[16]||(t[16]=[n("ul",null,[n("li",null,[n("a",{href:"./knob-bank"},"Knob snapshots"),o(" — Take and recall")]),n("li",null,[n("a",{href:"./lanes"},"Arrange"),o(" — Play snapshots as a song")]),n("li",null,[n("a",{href:"./../perform/knob-view#snapshot-and-morph-knobs"},"Snapshot and morph knobs on Perform")]),n("li",null,[n("a",{href:"./"},"Snapshots"),o(" — Overview")])],-1)])]),_:1})])}const c=h(f,[["render",A]]);export{y as __pageData,c as default};
